import React, { useState, useEffect } from 'react';
import axios from 'axios';
import Equipment from './components/Equipment';
import EquipmentSearch from './components/EquipmentSearch';

function App() {
  const [equipmentData, setEquipmentData] = useState([]);  // Initialized as an empty array
  const [currentPage, setCurrentPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const itemsPerPage = 20;

  // Fetch data from API based on the current page
  const fetchData = async (searchTerm = '', category = 'all', minPrice = '', maxPrice = '') => {
    setLoading(true);
    try {
      const response = await axios.get('/api/equipment', {
        params: { 
          page: currentPage, 
          search: searchTerm, 
          category, 
          min_price: minPrice, 
          max_price: maxPrice 
        }
      });
      setEquipmentData(response.data.equipment);  // Data for the current page
      setTotalPages(response.data.total_pages);   // Total pages for pagination
      setLoading(false);
    } catch (error) {
      setError('Failed to load data');
      setLoading(false);
    }
  };

  // Fetch data when the page loads or when currentPage changes
  useEffect(() => {
    fetchData();  // Initial load
  }, [currentPage]);

  const nextPage = () => {
    if (currentPage < totalPages) {
      setCurrentPage((prevPage) => prevPage + 1);
    }
  };

  const prevPage = () => {
    if (currentPage > 1) {
      setCurrentPage((prevPage) => prevPage - 1);
    }
  };

  const handleSearch = (searchTerm, category, minPrice, maxPrice) => {
    setCurrentPage(1);  // Reset to the first page when searching
    fetchData(searchTerm, category, minPrice, maxPrice);
  };

  if (loading) return <p>Loading...</p>;
  if (error) return <p>{error}</p>;

  return (
    <div>
      <EquipmentSearch onSearch={handleSearch} />
      <Equipment equipment={equipmentData} />

      <div style={{ display: 'flex', justifyContent: 'center', marginTop: '10px' }}>
        <button onClick={prevPage} disabled={currentPage === 1}>Previous</button>
        <span style={{ margin: '0 10px' }}>Page {currentPage} of {totalPages}</span>
        <button onClick={nextPage} disabled={currentPage === totalPages}>Next</button>
      </div>
    </div>
  );
}

export default App;
